    "action": "visualize",
    "display_instruction": "各月 **OT 油温** 分布，观察月度季节周期",
    "input_tables": ["etth1_csv"],
    "code": "import pandas as pd\n\ndf = pd.read_parquet('data/etth1_csv.parquet')\ndf['date'] = pd.to_datetime(df['date'])\ndf['month'] = df['date'].dt.month\n\n# 为箱线图准备数据：month 和 OT 两列即可\nresult = df[['month', 'OT']].copy()\nresult.columns = ['月份', '油温']\n\noutput_variable = result",
